using LibreKO.Editors.Contracts;
using LibreKO.Editors.DataHost;
using LibreKO.Editors.Core;
using LibreKO.Common.Domain.Entities;
using LibreKO.Common.Enums;
using LibreKO.Common.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

public class AccountTests {
 const string Cs="Server=127.0.0.1;Port=33307;Database=libreko_editor_test_native;User=root;Pooling=false;";
 static AppDbContext Context()=>new(new DbContextOptionsBuilder<AppDbContext>().UseMySql(Cs,new MySqlServerVersion(new Version(8,2,0))).Options);
 static async Task<EditorDatabase> Fixture(){
  await using var db=Context();await db.Database.EnsureCreatedAsync();var a=await db.Accounts.FindAsync(310001);
  if(a==null){a=new Account{Id=310001,Login="account_editor_fixture",Password="secret-account-password",VipPassword="9876",SealCode="secret12",VipWarehouseItems=[4,8],Nation=AccountNation.Karus};db.Accounts.Add(a);}
  a.Authority=AccountAuthority.Normal;a.KnightCash=100;a.OnlineServerId=null;a.OnlineSince=null;a.PremiumType=0;a.PremiumDate=null;
  foreach(var id in new[]{710001,710002}){var c=await db.Characters.FindAsync(id);if(c==null){c=new Character{Id=id,AccountId=a.Id,Slot=(byte)(id-710001),Name="Account fixture "+id,Race=1,Class=101,Level=1,Items=new byte[2016],Money=25};db.Characters.Add(c);}c.IsOnline=false;}
  await db.SaveChangesAsync();return new(Cs,Path.Combine(Path.GetTempPath(),"account-editor-test-"+Guid.NewGuid()));
 }
 [Fact] public async Task AccountReadsAndSchemaExcludeSecrets(){var service=await Fixture();var row=(await service.GetAsync(new(RecordKind.Account,310001)))!;Assert.Equal("account_editor_fixture",row.Values["Login"]!.GetValue<string>());foreach(var name in new[]{"Password","VipPassword","SealCode","VipWarehouseItems"}){Assert.False(row.Values.ContainsKey(name));Assert.DoesNotContain(FieldSchema.For(RecordKind.Account),f=>f.Name==name);}var fields=FieldSchema.For(RecordKind.Account);Assert.Equal("Game master",fields.Single(f=>f.Name=="Authority").Choices!["0"]);Assert.True(fields.Single(f=>f.Name=="KnightCash").Writable);Assert.False(fields.Single(f=>f.Name=="OnlineServerId").Writable);var page=await service.ListAsync(RecordKind.Account,new("account_editor_fixture"));Assert.Contains(page.Rows,r=>r.Key.Id==310001);}
 [Fact] public async Task AccountChangesPersistAndRejectStaleSnapshots(){var service=await Fixture();var before=(await service.GetAsync(new(RecordKind.Account,310001)))!;var result=await service.SaveAsync(new(Guid.NewGuid(),before,new(){["Authority"]=0,["KnightCash"]=5000,["PremiumDate"]="2030-01-02T03:04:05Z"}));Assert.Equal(SaveStatus.Saved,result.Status);await using var db=Context();var stored=(await db.Accounts.FindAsync(310001))!;Assert.Equal(AccountAuthority.GameMaster,stored.Authority);Assert.Equal(5000,stored.KnightCash);Assert.Equal(new DateTime(2030,1,2,3,4,5),stored.PremiumDate);Assert.Equal("secret-account-password",stored.Password);Assert.Equal("9876",stored.VipPassword);Assert.Equal("secret12",stored.SealCode);Assert.Equal(new byte[]{4,8},stored.VipWarehouseItems);Assert.Equal(25,(await db.Characters.FindAsync(710001))!.Money);Assert.Equal(SaveStatus.Conflict,(await service.SaveAsync(new(Guid.NewGuid(),before,new(){["KnightCash"]=8}))).Status);}
 [Theory][InlineData("KnightCash",-1)][InlineData("Authority",99)][InlineData("OnlineServerId",1)] public async Task AccountInvalidOrSessionChangesAreRejected(string field,int value){var service=await Fixture();var before=(await service.GetAsync(new(RecordKind.Account,310001)))!;Assert.Equal(SaveStatus.Invalid,(await service.SaveAsync(new(Guid.NewGuid(),before,new(){[field]=value}))).Status);}
 [Fact] public async Task AccountSaveChecksEveryCharactersOnlineState(){var service=await Fixture();var before=(await service.GetAsync(new(RecordKind.Account,310001)))!;await using var db=Context();await db.Characters.Where(c=>c.Id==710002).ExecuteUpdateAsync(s=>s.SetProperty(c=>c.IsOnline,true));try{Assert.True((await service.GetAsync(before.Key))!.IsOnline);Assert.Equal(SaveStatus.Online,(await service.SaveAsync(new(Guid.NewGuid(),before,new(){["KnightCash"]=1}))).Status);}finally{await db.Characters.Where(c=>c.Id==710002).ExecuteUpdateAsync(s=>s.SetProperty(c=>c.IsOnline,false));}}
 [Fact] public async Task AccountCannotAcceptInventoryOrSecretEdits(){var service=await Fixture();var before=(await service.GetAsync(new(RecordKind.Account,310001)))!;Assert.Equal(SaveStatus.Invalid,(await service.SaveAsync(new(Guid.NewGuid(),before,new(){["Password"]="new secret"}))).Status);Assert.Equal(SaveStatus.Invalid,(await service.SaveAsync(new(Guid.NewGuid(),before,new(),Inventory:[]))).Status);}
 [Fact] public async Task DateHistoryReconcilesAndReversesAfterDatabaseRoundtrip(){await Fixture();var root=Path.Combine(Path.GetTempPath(),"account-date-recovery-"+Guid.NewGuid());Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"changes"),"injected history failure");var service=new EditorDatabase(Cs,root);var before=(await service.GetAsync(new(RecordKind.Account,310001)))!;var field=FieldSchema.For(RecordKind.Account).Single(f=>f.Name=="PremiumDate");var change=new RecordChange(Guid.NewGuid(),before,new(){["PremiumDate"]=FieldValueParser.Parse(field,"2030-01-02 03:04:05")});var result=await service.SaveAsync(change);Assert.Equal(SaveStatus.Saved,result.Status);Assert.Equal(RecoveryDisposition.Applied,RecoveryResolver.Resolve(change,result.Record));var pending=Assert.Single(new OperationJournal(root).Pending());Assert.Equal(RecoveryDisposition.Applied,RecoveryResolver.Resolve(pending,result.Record));var reverse=ChangeReplay.Prepare(pending,result.Record!,result.Record!,true);Assert.Null(reverse.ChangedValues["PremiumDate"]);}
}
